def max_of_three(a, b, c):
    biggest = a
    if b > biggest:
        biggest = b
    if c > biggest:
        biggest = c
    return biggest

def grade(score):
    if score >= 85:
        return "отлично"
    elif score >= 70:
        return "хорошо"
    elif score >= 50:
        return "удовлетворительно"
    else:
        return "плохо"
